"""One scene-independent network modifier around the unchanged junction kernel.

The collection contains disposable, controller-local metre-space carrier meshes.
Each collection child is kept as an instance until its loop iteration: realizing
all children together would invalidate the kernel's local record indices.
"""
import bpy
from . import live_input_nodes

NAME = 'Prochitecture Streets / Editable network v3'
REVISION = 1


